b aoi 2026-01-05 14:00 15:00 w; [ $? = 0 ] || { echo "omitted people should be treated as 1 and accepted"; fail=1; }
out=$(BOOKINGS=$t bash src/book.sh aoi 2026-01-05 16:00 17:00 v 5 2>/dev/null)
[ -z "$out" ] || { echo "over capacity message should go to stderr, not stdout"; fail=1; }
rm -f "$t"; exit $fail

